"""Edition flag: owner or client (CLIENT-PACKAGE-SPEC §1; D81, D86).

A file named `EDITION` at the package root (the directory that holds `gammad/`, `REPO_ROOT`) selects it:

    "client"                -> "client"  (the client ZIP ships it, generated by the packager)
    "owner"                 -> "owner"   (the owner's repo carries a tracked `EDITION` file, W14 H6)
    absent / unreadable /   -> "client"  + one ERROR line. A lost or damaged flag fails CLOSED to the more
    any other                            restrictive edition (E2 hidden, no automated broker login), never open
                                         (W14 H6, audit #15: a missing file used to mean "owner").

Case, surrounding whitespace and a UTF-8 BOM are ignored. It is NOT an `.env` key: the client `.env` holds
only Telegram + broker values (D81).

What the edition gates here:
  * `visible_kinds()` -> ("E1",) for the client, ("E1", "E2") for the owner (CLIENT §1-2).
  * `client_entry_kind()` -> the kind of the group / client V1 entry rows: "E1" in a client store (its E2 bar close
    entry is stored as E1, D288), "E2" in the owner's (0.8.5, D287(1)).
  * `top_n_oi(cfg)` -> 2 strikes per stock per list for the client (0.8.5, D287(4); 1 before), `proximity.top_n_oi`
    for the owner (T-153).
  * `v2_lists()` -> the V2 Scanner's lists (owner; the client edition has no V2 Scanner since 0.8.5, D287(6)).
  * `require_owner(feature)` raises `OwnerOnlyError` in the client edition. D86: client broker login is
    NEVER automated -- `gammad/auth/totp.py` and `gammad/auth/oauth.py` call it at import AND inside every
    public function, and `gammad.broker.registry.auto_login` calls it before touching an entry. A client
    pastes its token (or the broker's required credentials) in `.env` or on the Token page instead.

The value is read once, at import, into `EDITION`. Every helper reads that module global at CALL time, so
tests flip it with `monkeypatch.setattr(edition, "EDITION", "client")`.

Honest limit (CLIENT §1): the package is readable Python, so the edition is a presentation and behaviour
rule, not a protection against a client who edits the source.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

from gammad import REPO_ROOT
from gammad.log import get_logger

log = get_logger(__name__)

EDITION_FILE = "EDITION"
OWNER = "owner"
CLIENT = "client"
EDITIONS: tuple[str, ...] = (OWNER, CLIENT)

KIND_E1 = "E1"
KIND_E2 = "E2"


class OwnerOnlyError(PermissionError):
    """An owner-edition-only feature (automated broker login, E2) was reached from the client edition."""


def read_edition(root: Path | None = None) -> str:
    """Resolve the edition from `<root>/EDITION` (default: the package root). Never raises."""
    path = (root or REPO_ROOT) / EDITION_FILE
    try:
        raw = path.read_bytes()
    except FileNotFoundError:  # W14 H6: a lost flag fails CLOSED, never to the owner edition
        log.error("edition: %s missing; running as %s", path, CLIENT)
        return CLIENT
    except OSError as exc:  # a directory, a locked file ...: fail closed
        log.error("edition: %s unreadable (%s); running as %s", path, type(exc).__name__, CLIENT)
        return CLIENT
    text = raw.decode("utf-8-sig", errors="replace").strip().lower()
    if text in EDITIONS:
        return text
    log.error("edition: %s holds %r (not owner/client); running as %s", path, text[:40], CLIENT)
    return CLIENT


EDITION: str = read_edition()


def edition() -> str:
    return EDITION


def is_client() -> bool:
    return EDITION != OWNER  # anything but an explicit owner is treated as client (fail closed)


def is_owner() -> bool:
    return not is_client()


def visible_kinds() -> tuple[str, ...]:
    """Signal kinds this edition may store, show or send: E1 only for the client (D81, D85 rule 4)."""
    return (KIND_E1,) if is_client() else (KIND_E1, KIND_E2)


def client_entry_kind(client: bool | None = None) -> str:
    """0.8.5 (D287(1), D288, PLAN-D287 I3 / AM5): the ONE answer to "which rows of this store are the group / client V1
    entries". The client's V1 entry is the E2 bar close; the CLIENT router stores it as kind E1 (the engine's own E1 is
    dropped there), the OWNER store keeps it as kind E2 (its E1s are the owner's personal entries). `client` None = the
    running edition (read at CALL time); True -> "E1"; False -> "E2" (like `v2_lists(owner)`)."""
    is_client_ed = is_client() if client is None else bool(client)
    return KIND_E1 if is_client_ed else KIND_E2


# T-153, D120(4)/D126 (one strike); 0.8.5 D287(4) (PLAN-D287 I6): the client's lists carry TWO strikes per stock
# (HOI-1 and HOI-2), and ONE entry per stock per day (R4)
CLIENT_TOP_N_OI = 2


def top_n_oi(cfg: Any) -> int:
    """Strikes per (stock, list) the list build keeps: CLIENT_TOP_N_OI (2, D287(4)) for the client edition (its two
    lists, D429; the yaml stays at the owner's value and there is no spec bump: list size is not a signal rule, D126),
    `cfg.proximity.top_n_oi` for the owner. Research (backtest/runner.py) keeps reading the yaml value: research = owner
    rules."""
    return CLIENT_TOP_N_OI if is_client() else int(cfg.proximity.top_n_oi)


ALL_LISTS: tuple[str, ...] = ("BREAKDOWN-PE", "BREAKOUT-CE", "EXPIRY-PE", "EXPIRY-CE")  # = config.HOLD_ALL_LISTS
CLIENT_V2_LISTS: tuple[str, ...] = ("BREAKDOWN-PE", "BREAKOUT-CE")


def v2_lists(owner: bool | None = None) -> tuple[str, ...]:
    """The watchlist lists the V2 Scanner (V2T, S1.7.0) runs on (D248(7), STRATEGY-SPEC 4.7): every list for the owner.
    The client edition runs no V2 Scanner since 0.8.5 (D287(6)); `owner=False` still returns the pre-0.8.5 client
    lists ("BREAKDOWN-PE", "BREAKOUT-CE") for a caller that passes the flag. `owner` None = the
    running edition (read at CALL time); the scanner registry passes its own flag."""
    is_owner_ed = is_owner() if owner is None else bool(owner)
    return ALL_LISTS if is_owner_ed else CLIENT_V2_LISTS


# 0.8.8 (D429, owner): the CLIENT edition's V1 builds, shows, alerts and trades ONLY the BREAKDOWN-PE / BREAKOUT-CE lists
# (the current month, or the NEXT month in expiry week: STRATEGY-SPEC 2.1, so clients still trade expiry week on the
# next-month rows); NO EXPIRY-PE / EXPIRY-CE list. The owner keeps all four (ALL_LISTS). The ONE source every client
# path reads (the list build, load_day's engines, the feed set, the posts, /api/watchlists): v1_lists / v1_list_ok /
# v1_lists_sql below. Kept BELOW ALL_LISTS so the Lab's pinned call sites (edition.py:105 / :116) do not move.
CLIENT_V1_LISTS: tuple[str, ...] = ("BREAKDOWN-PE", "BREAKOUT-CE")


def v1_lists(owner: bool | None = None) -> tuple[str, ...]:
    """The watchlist lists the live V1 scanner builds, shows, alerts and trades (D429): CLIENT_V1_LISTS for the client
    edition, ALL_LISTS for the owner. `owner` None = the running edition (read at CALL time), like `v2_lists`."""
    is_owner_ed = is_owner() if owner is None else bool(owner)
    return ALL_LISTS if is_owner_ed else CLIENT_V1_LISTS


def v1_list_ok(list_name: Any, owner: bool | None = None) -> bool:
    """D429: may this edition's V1 build / show / alert / trade a row of `list_name`? The OWNER edition: always (its
    behaviour is unchanged, a list outside ALL_LISTS included). The CLIENT edition: only a CLIENT_V1_LISTS list (an
    unknown / None list is refused: fail closed)."""
    is_owner_ed = is_owner() if owner is None else bool(owner)
    return True if is_owner_ed else (list_name is not None and str(list_name) in CLIENT_V1_LISTS)


def v1_lists_sql(owner: bool | None = None, column: str = "list_name") -> str:
    """D429: the SQL clause a watchlist read appends so the CLIENT edition never reads an EXPIRY row: "" for the owner
    (the query is byte-identical to before), ` AND <column> IN ('BREAKDOWN-PE', 'BREAKOUT-CE')` for the client. The
    names are this module's constants (no user input reaches the string)."""
    is_owner_ed = is_owner() if owner is None else bool(owner)
    if is_owner_ed:
        return ""
    return f" AND {column} IN (" + ", ".join(f"'{n}'" for n in CLIENT_V1_LISTS) + ")"


# 0.8.9 T-419 (D471 Q1 / Q7 / Q8 / Q10, D480): the CLIENT edition's THIRD list, "Still Watching" = the carried contracts
# (watchlist rows tagged CARRY: the internal word, never shown to a client, D437). A client sees them under exactly this
# name, beside CLIENT_V1_LISTS, and their ENTRY cards reach its app, bot and group. Kept BELOW CLIENT_V1_LISTS so the
# Lab's pinned call sites (edition.py:105 / :116 / :134) do not move.
CLIENT_STILL_WATCHING = "Still Watching"
CARRY_TAG = "CARRY"  # = jobs.carry.CARRY_TAG / router.TAG_CARRY: the internal tag of a carried row (never client-facing)


def still_watching_on(cfg: Any = None) -> bool:
    """D471 Q10 / D480: is the Still Watching list switched on? `cfg` = Settings, Settings.still_watching, or None.
    Read DEFENSIVELY (Settings.still_watching lands with the T-419 config builder): no block / no `enabled` key ->
    True (D471 Q10 "switch on for clients in 0.8.9"; config/strategy.yaml `still_watching.enabled: true`)."""
    if cfg is None:
        return True
    block = getattr(cfg, "still_watching", cfg)
    if isinstance(block, dict):
        return bool(block.get("enabled", True))
    return bool(getattr(block, "enabled", True))


def carry_visible(cfg: Any = None, owner: bool | None = None) -> bool:
    """May this edition show / alert / trade a carried (CARRY-tagged) row? The OWNER edition: always (its carry rows are
    unchanged); the CLIENT edition: only while Still Watching is on (`still_watching_on`), and then only under the list
    name CLIENT_STILL_WATCHING. `owner` None = the running edition (read at CALL time)."""
    is_owner_ed = is_owner() if owner is None else bool(owner)
    return True if is_owner_ed else still_watching_on(cfg)


def require_owner(feature: str) -> None:
    """Raise OwnerOnlyError when `feature` is reached from the client edition (D86)."""
    if is_client():
        raise OwnerOnlyError(
            f"{feature} is owner-edition only (D86): the client edition never automates broker login; "
            "paste the access token (or the broker's credentials) in .env or on the Broker login page"
        )
